import json
from docx import Document

TEMPLATE = '/root/offer_letter_template.docx'
DATA = '/root/employee_data.json'
OUTPUT = '/root/offer_letter_filled.docx'

with open(DATA, 'r', encoding='utf-8') as f:
    data = json.load(f)

mapping = {f"{{{{{k}}}}}": str(v) for k, v in data.items()}

relocation_enabled = str(data.get('RELOCATION_PACKAGE', '')).strip().lower() == 'yes'

START = '{{IF_RELOCATION}}'
END = '{{END_IF_RELOCATION}}'


def remove_paragraph(paragraph):
    p = paragraph._element
    p.getparent().remove(p)


def replace_placeholders_in_paragraph(paragraph, mapping):
    # First pass: simple run replacements
    for run in paragraph.runs:
        for key, value in mapping.items():
            if key in run.text:
                run.text = run.text.replace(key, value)

    # If any placeholders remain (split across runs), fallback to merge
    if any(key in paragraph.text for key in mapping.keys()):
        text = paragraph.text
        for key, value in mapping.items():
            if key in text:
                text = text.replace(key, value)
        # Clear runs and set merged text
        if paragraph.runs:
            for run in paragraph.runs:
                run.text = ''
            paragraph.runs[0].text = text
        else:
            paragraph.add_run(text)


def handle_relocation(paragraph):
    if START in paragraph.text or END in paragraph.text:
        if not relocation_enabled:
            remove_paragraph(paragraph)
            return False
        # keep content, strip markers
        for run in paragraph.runs:
            if START in run.text or END in run.text:
                run.text = run.text.replace(START, '').replace(END, '')
    return True


def iter_paragraphs(doc):
    for p in list(doc.paragraphs):
        yield p
    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                for p in list(cell.paragraphs):
                    yield p
    for section in doc.sections:
        for p in list(section.header.paragraphs):
            yield p
        for p in list(section.footer.paragraphs):
            yield p


doc = Document(TEMPLATE)

for paragraph in list(iter_paragraphs(doc)):
    if not handle_relocation(paragraph):
        continue
    replace_placeholders_in_paragraph(paragraph, mapping)

# Optional: clean any leftover markers if present in combined text
for paragraph in list(iter_paragraphs(doc)):
    if START in paragraph.text or END in paragraph.text:
        for run in paragraph.runs:
            run.text = run.text.replace(START, '').replace(END, '')

# Verify no placeholders remain (best-effort)
# Note: intentionally not raising to avoid blocking save in case of formatting-only leftovers

doc.save(OUTPUT)
print('saved', OUTPUT)
PY"}

